import React, { useState } from 'react';
import Blobs from '../components/Blobs';
import Orb3D from '../components/Orb3D';
import { analyzeThought } from '../hooks/useGroq';
import { useThoughts } from '../hooks/useStorage';

export default function Home({ setPage, streak }) {
  const [text,    setText]    = useState('');
  const [loading, setLoading] = useState(false);
  const [error,   setError]   = useState('');
  const [result,  setResult]  = useState(null);
  const { addThought } = useThoughts();

  const handleSubmit = async () => {
    if (!text.trim() || loading) return;
    setLoading(true); setError('');
    try {
      const ai = await analyzeThought(text);
      const entry = { id:Date.now(), user_text:text, ...ai, date:new Date().toISOString() };
      addThought(entry);
      setResult(entry);
    } catch { setError('Kunde inte analysera just nu. Försök igen.'); }
    setLoading(false);
  };

  if (result) return <Analysis result={result} text={text} onBack={()=>{ setResult(null); setText(''); }} setPage={setPage} />;

  return (
    <div style={{ minHeight:'100vh', position:'relative', overflow:'hidden' }}>
      <Blobs variant="default" />

      {/* Giant orb — bleeds off top-right like the Air OS reference */}
      <div style={{ position:'absolute', top:'-22%', right:'-20%', zIndex:0, opacity:0.85, pointerEvents:'none', animation:'drift 14s ease-in-out infinite' }}>
        <Orb3D size={520} colors={['#5030b0','#180c48','#8050e0']} speed={0.2} />
      </div>

      <div style={{ position:'relative', zIndex:1, minHeight:'100vh', display:'flex', flexDirection:'column', justifyContent:'flex-end', padding:'80px 32px 48px', maxWidth:520, margin:'0 auto' }}>

        {/* Header — top left, large type breaks across */}
        <div style={{ position:'absolute', top:88, left:32, right:32 }}>
          {streak > 0 && (
            <div style={{ display:'inline-flex', alignItems:'center', gap:7, padding:'4px 12px', borderRadius:100, background:'rgba(255,255,255,0.07)', border:'1px solid rgba(255,255,255,0.1)', marginBottom:20, fontSize:11, color:'rgba(255,255,255,0.5)', fontFamily:'DM Mono,monospace', letterSpacing:'0.08em' }}>
              🔥 {streak} dag{streak>1?'ar':''} i rad
            </div>
          )}
          <h1 style={{ fontSize:'clamp(44px,10vw,76px)', fontWeight:700, letterSpacing:'-0.055em', lineHeight:0.86, color:'#fff' }}>
            BRYT<br/>
            <span style={{ color:'rgba(255,255,255,0.2)' }}>TANKE-<br/>SPIRALEN</span>
          </h1>
        </div>

        {/* Bottom section — input + nav */}
        <div style={{ display:'flex', flexDirection:'column', gap:10 }}>

          {/* Small label */}
          <div style={{ display:'flex', alignItems:'center', gap:10, marginBottom:4 }}>
            <div style={{ width:5, height:5, borderRadius:'50%', background:'rgba(140,100,255,0.9)', animation:'pulse 2s infinite' }} />
            <span style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(255,255,255,0.28)' }}>Vad snurrar i huvudet just nu?</span>
          </div>

          {/* Input — minimal, barely there */}
          <div className="glass" style={{ borderRadius:20, padding:'20px 22px' }}>
            <textarea value={text} onChange={e=>setText(e.target.value)} maxLength={1000}
              placeholder="Skriv fritt... AI:n identifierar tankefällan"
              style={{ width:'100%', minHeight:110, background:'transparent', border:'none', color:'#fff', fontSize:15, fontWeight:300, lineHeight:1.75, resize:'none', outline:'none', placeholder:'rgba(255,255,255,0.2)' }}
            />
            <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', paddingTop:14, borderTop:'1px solid rgba(255,255,255,0.06)' }}>
              <span style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(255,255,255,0.18)' }}>{text.length}/1000</span>
              <button onClick={handleSubmit} disabled={!text.trim()||loading}
                style={{ padding:'10px 22px', borderRadius:100, fontSize:13, fontWeight:600, transition:'all .3s', background: text.trim()&&!loading ? '#fff' : 'rgba(255,255,255,0.08)', color: text.trim()&&!loading ? '#13121a' : 'rgba(255,255,255,0.2)' }}>
                {loading
                  ? <span style={{ display:'flex',alignItems:'center',gap:8 }}><span style={{ width:11,height:11,border:'2px solid rgba(0,0,0,0.2)',borderTopColor:'#000',borderRadius:'50%',display:'inline-block',animation:'spin .7s linear infinite' }}/>Analyserar...</span>
                  : 'Analysera →'}
              </button>
            </div>
            {error && <p style={{ color:'rgba(255,120,120,0.8)', fontSize:12, marginTop:10 }}>{error}</p>}
          </div>

          {/* Quick nav — horizontal pills */}
          <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:10 }}>
            <button onClick={()=>setPage('checkin')} className="glass"
              style={{ padding:'14px 18px', borderRadius:16, display:'flex', alignItems:'center', gap:10, color:'rgba(255,255,255,0.55)', fontSize:13, transition:'all .2s' }}
              onMouseEnter={e=>{e.currentTarget.style.color='#fff';e.currentTarget.style.background='rgba(255,255,255,0.09)'}}
              onMouseLeave={e=>{e.currentTarget.style.color='rgba(255,255,255,0.55)';e.currentTarget.style.background='rgba(255,255,255,0.055)'}}>
              <span style={{ fontSize:18 }}>✅</span>
              <div style={{ textAlign:'left' }}>
                <div style={{ fontSize:12, fontWeight:500 }}>Check-in</div>
                <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(255,255,255,0.28)', marginTop:1 }}>Hur mår du?</div>
              </div>
            </button>
            <button onClick={()=>setPage('breathing')} className="glass"
              style={{ padding:'14px 18px', borderRadius:16, display:'flex', alignItems:'center', gap:10, color:'rgba(255,255,255,0.55)', fontSize:13, transition:'all .2s' }}
              onMouseEnter={e=>{e.currentTarget.style.color='#fff';e.currentTarget.style.background='rgba(255,255,255,0.09)'}}
              onMouseLeave={e=>{e.currentTarget.style.color='rgba(255,255,255,0.55)';e.currentTarget.style.background='rgba(255,255,255,0.055)'}}>
              <span style={{ fontSize:18 }}>🫁</span>
              <div style={{ textAlign:'left' }}>
                <div style={{ fontSize:12, fontWeight:500 }}>Andning</div>
                <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(255,255,255,0.28)', marginTop:1 }}>4-7-8 teknik</div>
              </div>
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

function Analysis({ result, text, onBack, setPage }) {
  return (
    <div style={{ minHeight:'100vh', position:'relative', overflow:'hidden' }}>
      <Blobs variant="warm" />

      {/* Orb off-screen top-left for analysis */}
      <div style={{ position:'absolute', top:'-25%', left:'-22%', zIndex:0, opacity:0.75, pointerEvents:'none', animation:'drift 10s ease-in-out infinite' }}>
        <Orb3D size={440} colors={['#901840','#3a0818','#c03060']} speed={0.15} />
      </div>

      <div style={{ position:'relative', zIndex:1, padding:'80px 32px 60px', maxWidth:520, margin:'0 auto', animation:'fadeUp .6s cubic-bezier(0.16,1,0.3,1) both' }}>

        {/* What you wrote — small, at top */}
        <div style={{ borderLeft:'2px solid rgba(255,255,255,0.1)', paddingLeft:16, marginBottom:36, fontSize:13, color:'rgba(255,255,255,0.3)', fontStyle:'italic', lineHeight:1.7 }}>"{text.slice(0,140)}{text.length>140?'...':''}"</div>

        {/* Trap — big type */}
        <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.22em', textTransform:'uppercase', color:'rgba(255,255,255,0.25)', marginBottom:10 }}>
          {result.trap_icon} Tankefälla
        </p>
        <h2 style={{ fontSize:'clamp(36px,8vw,58px)', fontWeight:700, letterSpacing:'-0.05em', lineHeight:0.88, color:'#fff', marginBottom:36 }}>
          {result.trap_label}
        </h2>

        {/* Info sections — clean, minimal */}
        {[
          { label:'Vad händer', body:result.description },
          { label:'Omramning',  body:result.reframe },
          { label:'Övning',     body:result.exercise_text },
        ].map(({ label, body }) => (
          <div key={label} style={{ marginBottom:20 }}>
            <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.18em', textTransform:'uppercase', color:'rgba(255,255,255,0.25)', marginBottom:8 }}>{label}</p>
            <div className="glass" style={{ borderRadius:16, padding:'18px 20px' }}>
              <p style={{ fontSize:14, color:'rgba(255,255,255,0.75)', lineHeight:1.85, fontWeight:300 }}>{body}</p>
            </div>
          </div>
        ))}

        {result.second_trap && result.second_trap !== 'null' && (
          <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(255,255,255,0.22)', marginBottom:20 }}>Möjlig sekundär: {result.second_trap}</p>
        )}

        <div style={{ display:'flex', gap:10, marginTop:8 }}>
          <button onClick={()=>setPage('breathing')} className="glass"
            style={{ flex:1, padding:'13px', borderRadius:14, color:'rgba(255,255,255,0.6)', fontSize:13, transition:'all .2s' }}
            onMouseEnter={e=>{e.currentTarget.style.color='#fff'}} onMouseLeave={e=>{e.currentTarget.style.color='rgba(255,255,255,0.6)'}}>
            🫁 Andningsövning
          </button>
          <button onClick={onBack} style={{ padding:'13px 20px', borderRadius:14, color:'rgba(255,255,255,0.28)', fontSize:13 }}>← Tillbaka</button>
        </div>
      </div>
    </div>
  );
}
